const req = $input.first().json || {};

const input = req.input || {};
const text = String(input.text || '').trim();
const textLower = text.toLowerCase();

const buttonAction = String(input.button_action || '').trim();
const normalizedAction = String(input.normalized_action || '').trim();

const rawAction = buttonAction || normalizedAction || 'UNKNOWN';

// =======================
// Helpers
// =======================

function mainMenuButtons() {
  return [
    [{ text: '📄 إنشاء CV', callback_data: 'CREATE_CV' }],
    [{ text: '🔍 تحليل CV', callback_data: 'ANALYZE_CV' }],
    [{ text: '🎯 مطابقة وظيفة', callback_data: 'MATCH_CV_WITH_JOB' }],
    [{ text: '⚡ تحسين CV', callback_data: 'OPTIMIZE_CV' }],
    [{ text: '✏️ تعديل CV', callback_data: 'EDIT_CV' }],
    [{ text: '❓ مساعدة', callback_data: 'HELP' }]
  ];
}

function directText(message) {
  return {
    ok: true,
    request_id: req.request_id,
    chat_id: req.meta?.chat_id || '',
    reply: {
      type: 'text',
      text: message,
      parse_mode: 'HTML',
      keyboard: mainMenuButtons()
    },
    meta: {
      source_workflow: 'WF_01_Assistant_Orchestrator',
      user_id: req.user?.id || '',
      session_id: ''
    }
  };
}

// =======================
// Action Mapping
// =======================

const actionMap = {
  START_CREATE_CV: 'CREATE_CV',
  CREATE_CV: 'CREATE_CV',

  START_ANALYZE_CV: 'ANALYZE_CV',
  ANALYZE_CV: 'ANALYZE_CV',

  START_OPTIMIZE_CV: 'OPTIMIZE_CV',
  OPTIMIZE_CV: 'OPTIMIZE_CV',
  GENERATE_OPTIMIZED_CV: 'OPTIMIZE_CV',
  GENERATE_OPTIMIZED_CV_PDF: 'OPTIMIZE_CV',

  START_MATCH_CV: 'MATCH_CV_WITH_JOB',
  MATCH_CV: 'MATCH_CV_WITH_JOB',
  MATCH_CV_WITH_JOB: 'MATCH_CV_WITH_JOB',

  START_EDIT_CV: 'EDIT_CV',
  EDIT_CV: 'EDIT_CV',

  HELP: 'HELP',
  MENU: 'MENU',
  MAIN_MENU: 'MENU',
  UNKNOWN: 'UNKNOWN'
};

let requestedService = actionMap[rawAction] || 'UNKNOWN';

// =======================
// Text fallback
// =======================

if (requestedService === 'UNKNOWN' && text) {
  if (
    text.includes('إنشاء') ||
    text.includes('انشاء') ||
    text.includes('سيرة') ||
    textLower.includes('create') ||
    textLower.includes('cv')
  ) {
    requestedService = 'CREATE_CV';
  } else if (
    text.includes('تحليل') ||
    text.includes('حلل') ||
    textLower.includes('analyze') ||
    textLower.includes('ats')
  ) {
    requestedService = 'ANALYZE_CV';
  } else if (
    text.includes('تحسين') ||
    text.includes('حسن') ||
    textLower.includes('optimize')
  ) {
    requestedService = 'OPTIMIZE_CV';
  } else if (
    text.includes('مطابقة') ||
    text.includes('وظيفة') ||
    textLower.includes('match') ||
    textLower.includes('job')
  ) {
    requestedService = 'MATCH_CV_WITH_JOB';
  } else if (
    text.includes('تعديل') ||
    text.includes('عدل') ||
    textLower.includes('edit')
  ) {
    requestedService = 'EDIT_CV';
  } else if (
    text.includes('مساعدة') ||
    textLower === 'help' ||
    textLower === '/help'
  ) {
    requestedService = 'HELP';
  } else if (
    text.includes('القائمة') ||
    textLower === '/start' ||
    textLower === '/menu'
  ) {
    requestedService = 'MENU';
  }
}

// =======================
// Service Plans
// =======================

const servicePlans = {
  CREATE_CV: {
    service: 'CREATE_CV',
    step: 'full_name',
    context_json: {
      next_expected_input: 'FULL_NAME'
    }
  },

  ANALYZE_CV: {
    service: 'ANALYZE_CV',
    step: 'upload_cv',
    context_json: {
      next_expected_input: 'CV_FILE'
    }
  },

  OPTIMIZE_CV: {
    service: 'OPTIMIZE_CV',
    step: 'generate_optimized_pdf',
    context_json: {
      next_expected_input: 'USE_LAST_CV_ANALYSIS'
    }
  },

  MATCH_CV_WITH_JOB: {
    service: 'MATCH_CV_WITH_JOB',
    step: 'job_description_or_cv',
    context_json: {
      match: {
        job_description: '',
        has_job_description: false,
        cv_analysis_id: null,
        user_file_id: null,
        has_cv_analysis: false,
        has_cv_file: false,
        ready_to_match: false,
        missing: ['job_description', 'cv_analysis']
      },
      next_expected_input: 'JOB_DESCRIPTION_OR_CV'
    }
  },

  EDIT_CV: {
    service: 'EDIT_CV',
    step: 'upload_or_instruction',
    context_json: {
      next_expected_input: 'EDIT_INSTRUCTION_OR_CV_FILE'
    }
  }
};

const isServiceRequest = Boolean(servicePlans[requestedService]);

let routePlan;

if (isServiceRequest) {
  const plan = servicePlans[requestedService];

  routePlan = {
    type: 'start_service',
    should_start_service: true,
    service: plan.service,
    active_service: plan.service,
    step: plan.step,
    current_step: plan.step,
    status: 'active',
    locked: true,
    context_json: plan.context_json || {},
    reason: 'new_service_request'
  };
} else if (requestedService === 'HELP') {
  routePlan = {
    type: 'direct_response',
    should_start_service: false,
    response: directText(
`هذه الخدمات المتاحة:

📄 إنشاء CV
🔍 تحليل CV
🎯 مطابقة CV مع وظيفة
⚡ تحسين CV
✏️ تعديل CV

اختر الخدمة التي تريدها من القائمة.`
    )
  };
} else {
  routePlan = {
    type: 'direct_response',
    should_start_service: false,
    response: directText(
`أهلًا ${req.user?.first_name || 'صديقي'} 👋

اختر الخدمة التي تريدها من القائمة:`
    )
  };
}

return [
  {
    json: {
      ...req,
      input: {
        ...req.input,
        normalized_action: requestedService
      },
      route_plan: routePlan,
      route: {
        requested_service: requestedService,
        should_start_service: routePlan.should_start_service === true,
        should_start_service_flag: routePlan.should_start_service ? 1 : 0
      }
    }
  }
];
